Problem Title: Reverse a Singly Linked List
Question Statement:
Given the head of a singly linked list, reverse the list, and return the reversed list.

Candidate's Answer / Code:
function reverseList(head) {
  let prev = null;
  let curr = head;
  while (curr !== null) {
    let nextTemp = curr.next;
    curr.next = prev;
    prev = curr;
    curr = nextTemp;
  }
  return prev;
}

